def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal change between two strings."""
    # Simple implementation to find first differing character
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            return (s_in[i], s_out[i], i)

    # If we reach here, one string is prefix of other
    if len(s_in) > len(s_out):
        return (s_in[min_len], '', min_len)
    elif len(s_in) < len(s_out):
        return ('', s_out[min_len], min_len)

    return None, None, -1

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates from a transformation."""
    # For simplicity, we'll create basic candidates
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    if old_sub and new_sub:
        # Most specific: exact character substitution
        candidates = [(old_sub, new_sub)]

        # Generalize to substring patterns if needed
        # But for now let's keep it simple

        return candidates
    else:
        return []

